  "(555) 123-4567": "(11) 91234-5678",
  "We also text them the link. Good for supervisors who don’t check email. The number is deleted after 30 days.": "Também mandamos o link por SMS, bom para quem não olha e-mail. O número é apagado após 30 dias.",
  "{organizer} reviews and signs this on their My Tasks page in VolunTrack — no email is sent.": "{organizer} revisa e assina isto na página Minhas tarefas do VolunTrack — nenhum e-mail é enviado.",
  "The task organizer": "O organizador da tarefa",
  "Your supervisor will get an email with a link to review these hours. If they approve, they'll sign right there to confirm it — if they reject, no signature is needed. This usually takes a day or two.": "Seu supervisor vai receber um e-mail com um link para revisar estas horas. Se aprovar, assina ali mesmo; se recusar, não precisa assinar. Isso costuma levar um ou dois dias.",
  "Supervisor signature": "Assinatura do supervisor",
  "Add your supervisor’s name — they’ll sign under Signatures below.": "Adicione o nome do supervisor — ele vai assinar em Assinaturas abaixo.",
