  "Open VolunTrack in your phone’s web browser (Chrome or Safari) using the button below, and sign in.": "Abra o VolunTrack no navegador do celular (Chrome ou Safari) com o botão abaixo e entre.",
  "Then use the browser’s translate, as shown below.": "Depois use a tradução do navegador, como mostrado abaixo.",
  "Use VolunTrack in another language": "Usar o VolunTrack em outro idioma",
  "VolunTrack is written in English, Spanish, Vietnamese and Chinese, and its main screens in Hindi, Arabic, Portuguese, French, Bengali, Russian and Japanese. For any other language, your browser can translate the page for you. It’s free and works for 100+ languages, like Tagalog, Korean, Haitian Creole, German and Urdu.": "O VolunTrack está em inglês, espanhol, vietnamita e chinês, e suas telas principais em hindi, árabe, português, francês, bengali, russo e japonês. Para qualquer outro idioma, seu navegador pode traduzir a página. É grátis e funciona em mais de 100 idiomas, como tagalo, coreano, crioulo haitiano, alemão e urdu.",
  "computer": "computador",
  "Right-click anywhere on the page, choose Translate to…, then pick your language.": "Clique com o botão direito em qualquer lugar da página, escolha Traduzir para… e selecione seu idioma.",
  "Android phone": "Celular Android",
  "Tap ⋮ (top right), then Translate…, then pick your language.": "Toque em ⋮ (canto superior direito), depois em Traduzir… e escolha seu idioma.",
  "iPhone": "iPhone",
  "Tap the page menu (aA or the icon at the left of the address bar), then Translate to….": "Toque no menu da página (aA ou o ícone à esquerda da barra de endereço) e depois em Traduzir para….",
  "Mac": "Mac",
  "Click the translate icon in the address bar, or choose View → Translation.": "Clique no ícone de tradução na barra de endereço ou escolha Visualizar → Tradução.",
  "Browser translation is done by your browser, not by VolunTrack, and may not be perfect. Emails still come in English or your chosen VolunTrack language.": "A tradução é feita pelo seu navegador, não pelo VolunTrack, e pode não ser perfeita. Os e-mails continuam chegando em inglês ou no idioma escolhido no VolunTrack.",
  "Open in browser": "Abrir no navegador",
