  "Tasks": "Tarefas",
  "School": "Escola",
  "Your hours and details are shared only with the school or organization you join, parents you link, and organizers of events you sign up for. We never sell your data or show ads.": "Suas horas e dados são compartilhados só com a escola ou organização em que você entra, os responsáveis que você vincula e os organizadores dos eventos em que se inscreve. Nunca vendemos seus dados nem mostramos anúncios.",
  "Log only hours you really did. Never sign for someone else or check in or out for them. False hours can get your account suspended.": "Registre só horas que você realmente fez. Nunca assine por outra pessoa nem faça check-in ou check-out por ela. Horas falsas podem suspender sua conta.",
  "If you are under 13, a parent or guardian must approve your account.": "Se você tem menos de 13 anos, um pai, mãe ou responsável precisa aprovar sua conta.",
  "Event organizers run their own events and keep volunteers safe; VolunTrack doesn't supervise them.": "Os organizadores cuidam dos próprios eventos e da segurança dos voluntários; o VolunTrack não os supervisiona.",
  "You can delete your account at any time in Settings, and your data is deleted with it.": "Você pode excluir sua conta a qualquer momento em Configurações, e seus dados são apagados com ela.",
  "If these terms change, we will show you what changed and ask you to agree again.": "Se estes termos mudarem, mostraremos o que mudou e pediremos que você aceite de novo.",
  "You see students' hours, documents and progress only to review and verify their service. Keep them private and use them for nothing else.": "Você vê horas, documentos e progresso dos alunos só para revisar e verificar o serviço deles. Mantenha tudo em sigilo e não use para mais nada.",
  "Paid school and organization accounts are billed by invoice; until a payment is verified, some tools may be paused. A free club stays free.": "Contas pagas de escola e organização são cobradas por fatura; até o pagamento ser verificado, algumas ferramentas podem ficar pausadas. Um clube grátis continua grátis.",
  "Approve or sign hours only when you believe they are right.": "Aprove ou assine horas só quando acreditar que estão corretas.",
  "We never sell anyone's data or show ads. Students, parents and volunteers keep their own free accounts.": "Nunca vendemos dados de ninguém nem mostramos anúncios. Estudantes, pais e voluntários mantêm suas próprias contas grátis.",
  "Your hours and details are shared only with the school you join, parents you link, and organizers of events you sign up for. We never sell your data or show ads.": "Suas horas e dados são compartilhados só com a escola em que você entra, os responsáveis que você vincula e os organizadores dos eventos em que se inscreve. Nunca vendemos seus dados nem mostramos anúncios.",
  "Event organizers run their own events and keep volunteers safe; VolunTrack doesn't supervise them. Give honest answers when you sign up, like your age.": "Os organizadores cuidam dos próprios eventos e da segurança dos voluntários; o VolunTrack não os supervisiona. Responda com sinceridade ao se inscrever, por exemplo sobre sua idade.",
  "Parent accounts are for adults 18 and over, and are free.": "Contas de pais são para adultos com 18 anos ou mais e são grátis.",
  "You see your child's hours read-only, after your child shares their link code with you. You can't change their entries.": "Você vê as horas do seu filho só para leitura, depois que ele compartilha o código de vínculo. Você não pode mudar os registros dele.",
  "Confirm or approve your child's hours and event sign-ups only when you know they are right.": "Confirme ou aprove as horas e inscrições do seu filho só quando souber que estão certas.",
  "We never sell your data or show ads. You can delete your account at any time in Settings.": "Nunca vendemos seus dados nem mostramos anúncios. Você pode excluir sua conta a qualquer momento em Configurações.",
  "Volunteer Task Maker accounts are for adults 18 and over, and are free.": "Contas de criador de tarefas são para adultos com 18 anos ou mais e são grátis.",
  "You run your events: keep the details accurate and up to date, and keep volunteers safe on the day. VolunTrack doesn't supervise events.": "Você cuida dos seus eventos: mantenha os dados corretos e atualizados e a segurança dos voluntários no dia. O VolunTrack não supervisiona eventos.",
  "Use volunteers' names and contact details only to run your event, and add co-hosts only if you trust them.": "Use nomes e contatos dos voluntários só para organizar seu evento, e adicione coanfitriões só se confiar neles.",
  "Share check-in PINs and codes only at the event, and sign hours only when you believe they are right.": "Compartilhe PINs e códigos de check-in só no evento, e assine horas só quando acreditar que estão corretas.",
  "Messages, photos and notes must be appropriate for young people. Reported posts can be removed.": "Mensagens, fotos e notas devem ser adequadas para jovens. Publicações denunciadas podem ser removidas.",
  "We never sell anyone's data or show ads. If these terms change, we will show you what changed and ask you to agree again.": "Nunca vendemos dados de ninguém nem mostramos anúncios. Se estes termos mudarem, mostraremos o que mudou e pediremos que você aceite de novo.",
  "You see your schools' students' hours and progress only to review and verify their service. Keep them private and use them for nothing else.": "Você vê as horas e o progresso dos alunos das suas escolas só para revisar e verificar o serviço deles. Mantenha tudo em sigilo e não use para mais nada.",
  "Organization accounts are billed by invoice; until a payment is verified, some tools may be paused.": "Contas de organização são cobradas por fatura; até o pagamento ser verificado, algumas ferramentas podem ficar pausadas.",
  "Send partner sign-off links only to a partner's real contact, and approve or sign hours only when you believe they are right.": "Envie links de confirmação de parceiros só para o contato real do parceiro, e aprove ou assine horas só quando acreditar que estão corretas.",
  "VolunTrack. All rights reserved.": "VolunTrack. Todos os direitos reservados.",
  "Waking up the server — this can take up to a minute after a quiet spell.": "Acordando o servidor — isso pode levar até um minuto depois de um tempo parado.",
  "Geolocation is not supported by your browser.": "Seu navegador não suporta geolocalização.",
