  "\". Business names aren't always mapped yet — try the full street address instead, or tap \"Current\" to pin your exact location.": "\". Nem todos os nomes de empresas estão no mapa ainda — tente o endereço completo ou toque em \"Atual\" para marcar sua localização exata.",
  "Not quite right? Drag the pin or click the map to adjust.": "Não ficou certo? Arraste o pino ou clique no mapa para ajustar.",
