  "Sign in and pick up where you left off—track hours, keep goals moving, and export your service record with confidence.": "Entre e continue de onde parou — registre horas, avance nas metas e exporte seu histórico de voluntariado com confiança.",
  "Fast logging": "Registro rápido",
