  "No approved hours yet for this period. Yours could be first!": "Nenhuma hora aprovada ainda neste período. As suas podem ser as primeiras!",
  "Nobody is on the leaderboard yet. Join and be the first!": "Ninguém está no ranking ainda. Entre e seja o primeiro!",
  "You're #{rank} with {hours} approved hours.": "Você está em #{rank} com {hours} horas aprovadas.",
  "You're on the leaderboard. Classmates see your first name, last initial and approved hours.": "Você está no ranking. Os colegas veem seu primeiro nome, a inicial do sobrenome e as horas aprovadas.",
  "Join to appear here. Only students at your school see it: your first name, last initial and approved hours.": "Entre para aparecer aqui. Só alunos da sua escola veem: seu primeiro nome, a inicial do sobrenome e as horas aprovadas.",
  "Join the leaderboard": "Entrar no ranking",
  "Monthly progress email": "E-mail mensal de progresso",
  "On. After a month you logged hours, we'll email you on the 1st with what you logged and how close you are to your goal.": "Ativado. Depois de um mês em que você registrou horas, vamos te mandar um e-mail no dia 1º com o que você registrou e quanto falta para sua meta.",
  "Off. We won't email you a monthly summary of your hours.": "Desativado. Não vamos enviar um resumo mensal das suas horas por e-mail.",
  "{name} invited you to VolunTrack": "{name} convidou você para o VolunTrack",
  "You're invited to VolunTrack": "Você foi convidado para o VolunTrack",
  "Track your volunteer hours free: log hours in a minute, see your goal, and download a report when it is due.": "Registre suas horas de voluntariado de graça: registre horas em um minuto, veja sua meta e baixe um relatório quando o prazo chegar.",
  "Log hours in under a minute, from your phone.": "Registre horas em menos de um minuto, pelo celular.",
  "See how close you are to your goal.": "Veja quanto falta para sua meta.",
  "Download a report when your hours are due.": "Baixe um relatório quando o prazo das suas horas chegar.",
  "The free way for students to track volunteer hours.": "O jeito grátis de alunos registrarem horas de voluntariado.",
  "You already have an account.": "Você já tem uma conta.",
  "I track my volunteer hours on VolunTrack. It is free. Join me:": "Eu registro minhas horas de voluntariado no VolunTrack. É grátis. Vem comigo:",
  "Earn the Bring a Friend badge when a friend joins with your link.": "Ganhe o selo Traga um amigo quando um amigo entrar pelo seu link.",
  "{n} of 5 friends joined. Reach 5 for the Team Builder badge.": "{n} de 5 amigos entraram. Chegue a 5 para ganhar o selo Formador de equipe.",
