  "Generate a 5-digit PIN to sync your account with your laptop. Enter it on your computer within 15 minutes — it works once.": "Gere um PIN de 5 dígitos para sincronizar sua conta com seu notebook. Digite-o no computador em até 15 minutos — funciona uma vez.",
  "Generate a 5-digit PIN to sync your account with the mobile app. Enter it on your phone within 15 minutes — it works once.": "Gere um PIN de 5 dígitos para sincronizar sua conta com o app para celular. Digite-o no celular em até 15 minutos — funciona uma vez.",
