  "Requesting…": "Solicitando…",
  "Request transfer": "Pedir transferência",
  "They will no longer see your hours or the reports you sent them. Your hours stay in your account, and you can join a school again with its code.": "Eles não vão mais ver suas horas nem os relatórios que você enviou. Suas horas ficam na sua conta, e você pode entrar numa escola de novo com o código dela.",
  "Leaving…": "Saindo…",
