  "School dashboard": "Painel da escola",
  "View students, review uploaded PDFs, and manage approvals.": "Veja os alunos, revise os PDFs enviados e gerencie aprovações.",
  "Open school dashboard": "Abrir painel da escola",
  "Students enter this in Settings → Join school to link their account to {school}.": "Os alunos digitam isto em Configurações → Entrar numa escola para vincular a conta a {school}.",
  "Copy school code": "Copiar código da escola",
