  "Letters followed by 3–5 digits, e.g. {example}. Students already linked to your school stay linked — only the code new students type changes.": "Letras seguidas de 3 a 5 dígitos, ex.: {example}. Alunos já vinculados à sua escola continuam vinculados — só muda o código que novos alunos digitam.",
  "Manage the schools your organization owns, review their hours, and invite new ones.": "Gerencie as escolas da sua organização, revise as horas delas e convide novas.",
  "Open organization dashboard": "Abrir painel da organização",
  "Organizations add schools by email invite from the dashboard — there is no organization-wide join code.": "As organizações adicionam escolas por convite por e-mail no painel — não há código de entrada para a organização toda.",
  "Family": "Família",
  "Share with a parent": "Compartilhar com um responsável",
  "Generate a code and share it with a parent so they can follow your logged hours and verification status. Only hours logged from now on will be visible to them. Each code works once — generate another for a second parent.": "Gere um código e compartilhe com um responsável para ele acompanhar suas horas registradas e o status de verificação. Só as horas registradas de agora em diante ficarão visíveis para ele. Cada código funciona uma vez — gere outro para um segundo responsável.",
