  "Manage reminders": "Gerenciar lembretes",
  "Privacy": "Privacidade",
  "Your logged hours are stored on this device. If you've created an account, some features above (Family sharing, school linking, cross-device sync, two-factor authentication) also store data on our server. Sign out below to clear your session.": "Suas horas registradas ficam guardadas neste aparelho. Se você criou uma conta, alguns recursos acima (compartilhamento com a família, vínculo com a escola, sincronização entre aparelhos, autenticação em dois fatores) também guardam dados no nosso servidor. Saia abaixo para limpar sua sessão.",
