  "Warning": "Atenção",
  "Deleting your account erases it from this device and from our servers, and cannot be undone.": "Excluir sua conta apaga ela deste aparelho e dos nossos servidores, e não pode ser desfeito.",
  "Delete account": "Excluir conta",
  "Remove your account and your VolunTrack data — from this device and, if you have an account with us, from our servers too. This action cannot be undone.": "Remova sua conta e seus dados do VolunTrack — deste aparelho e, se você tem conta com a gente, dos nossos servidores também. Esta ação não pode ser desfeita.",
  "Confirm account deletion": "Confirmar exclusão da conta",
