  "Passkeys": "Chaves de acesso",
  "After your password, confirm it’s you with Face ID, Touch ID, your fingerprint or your device PIN instead of typing a code. Keep your authenticator app too — its backup codes are how you get back in if you lose every device with a passkey.": "Depois da senha, confirme que é você com Face ID, Touch ID, sua digital ou o PIN do aparelho em vez de digitar um código. Mantenha também seu app autenticador — os códigos de backup dele são como você entra de novo se perder todos os aparelhos com chave de acesso.",
