  "Students enter this in Settings → Join school to link themselves to you, or use the join link in the starter kit below.": "Os alunos digitam isto em Configurações → Entrar numa escola para se vincular a você, ou usam o link de entrada do kit inicial abaixo.",
  "Transfer requests ({n})": "Pedidos de transferência ({n})",
