  "They get an email and accept in their Settings. You'll see them in your student list once they do. Students can also join with your school code.": "Ele recebe um e-mail e aceita nas Configurações. Você vai vê-lo na lista de alunos quando ele aceitar. Os alunos também podem entrar com o código da sua escola.",
