  "Export every student's logged hours for a date range — for administrators, service-hour compliance, or grant reporting.": "Exporte as horas registradas de todos os alunos num período — para a administração, controle de horas de serviço ou relatórios de financiamento.",
  "Volunteer hours report": "Relatório de horas de voluntariado",
