  "Let students sign in with your school's Google or Microsoft account instead of a VolunTrack password.": "Deixe os alunos entrarem com a conta Google ou Microsoft da escola em vez de uma senha do VolunTrack.",
  "Custom domain": "Domínio próprio",
  "Serve VolunTrack to your students on your own web address instead of the shared one.": "Ofereça o VolunTrack aos seus alunos no seu próprio endereço web em vez do compartilhado.",
  "Put your school's logo and colour on the sign-in page students see at your own web address.": "Coloque o logo e a cor da sua escola na página de login que os alunos veem no seu próprio endereço web.",
  "Add a co-admin": "Adicionar um coadministrador",
  "Co-admins can review uploads, manage students, and send announcements — {n}/10 used.": "Coadministradores podem revisar envios, gerenciar alunos e enviar avisos — {n}/10 usados.",
  "You've reached the limit of 10 co-admins. Remove one below to add another.": "Você chegou ao limite de 10 coadministradores. Remova um abaixo para adicionar outro.",
