  "New principal?": "Novo diretor?",
  "Hand this school’s main account to the person taking over. They get an email to accept and set their own password. You stay on as a co-admin until they remove you, and you’ll be signed out when they accept.": "Passe a conta principal desta escola para quem vai assumir. A pessoa recebe um e-mail para aceitar e criar a própria senha. Você continua como coadministrador até ela remover você, e sua sessão será encerrada quando ela aceitar.",
