  "Requirements saved.": "Requisitos salvos.",
  "Loading requirements…": "Carregando requisitos…",
  "Schools you assign to this template follow these sections instead of your defaults. A section left unset here uses your defaults, and a school can still set its own.": "As escolas que você atribuir a este modelo seguem estas seções em vez dos seus padrões. Uma seção não definida aqui usa seus padrões, e a escola ainda pode definir a própria.",
  "Every rule here applies to the students linked to your school. Anything you leave inherited follows your organization, or VolunTrack’s defaults if you have none.": "Toda regra aqui vale para os alunos vinculados à sua escola. O que ficar herdado segue sua organização, ou os padrões do VolunTrack se você não tiver uma.",
  "These are the defaults for every school you own. A school that sets its own version of a section keeps it — your changes reach the rest.": "Estes são os padrões de todas as escolas da sua organização. Uma escola que define a própria versão de uma seção a mantém — suas mudanças valem para as demais.",
  "Inherit": "Herdar",
