  "Minimum description length": "Tamanho mínimo da descrição",
  "Students can’t add, edit or delete entries dated before this, e.g. once a semester’s report is done. You can still add hours for them.": "Os alunos não podem adicionar, editar ou excluir registros com data anterior a esta, ex.: quando o relatório do semestre estiver pronto. Você ainda pode adicionar horas para eles.",
