  "Leave all unchecked to accept every category.": "Deixe tudo desmarcado para aceitar todas as categorias.",
  "Approved places": "Lugares aprovados",
  "One per line. Hours from anywhere else still go in, but they're flagged in Students → Hours to check so you can look at them first. Leave empty to accept every place.": "Um por linha. Horas de outros lugares ainda entram, mas ficam marcadas em Alunos → Horas para conferir para você olhar primeiro. Deixe em branco para aceitar qualquer lugar.",
  "Total hours required": "Total de horas exigido",
  "None": "Nenhum",
  "Deadline": "Prazo",
  "Grades at your school": "Séries da sua escola",
  "Tick the grades you have, e.g. only 9th, or 10th–12th. Students then pick from these, must pick one to join, and “New school year” moves your top grade on. Leave all unticked to allow any grade.": "Marque as séries que você tem, ex.: só o 9º, ou do 10º ao 12º. Os alunos escolhem entre elas, precisam escolher uma para entrar, e “Novo ano letivo” avança sua série mais alta. Deixe tudo desmarcado para permitir qualquer série.",
  "Note to students": "Mensagem para os alunos",
  "Due before senior year begins.": "Prazo: antes do início do último ano.",
  "Per-grade overrides": "Exceções por série",
  "A student in one of these grades is held to its number instead of the total above.": "Um aluno de uma destas séries segue o número dela em vez do total acima.",
  "Minimum hours by type": "Mínimo de horas por tipo",
  "At least this many of a student’s hours must be of one type. They count toward the total, not on top of it.": "Pelo menos esta quantidade das horas de um aluno precisa ser de um tipo. Elas contam no total, não além dele.",
  "Add a type": "Adicionar um tipo",
  "+ Add a type…": "+ Adicionar um tipo…",
  "Grade (e.g. 11, Junior, Year 12)": "Série (ex.: 11, 2º ano, Year 12)",
  "Students must sign in with our school account (SSO)": "Os alunos precisam entrar com a conta da escola (SSO)",
  "Allowed email domains": "Domínios de e-mail permitidos",
  "No levels yet.": "Nenhum nível ainda.",
  "Use Bronze, Silver, Gold": "Usar Bronze, Prata, Ouro",
  "Level name": "Nome do nível",
  "Add a level": "Adicionar um nível",
  "Hours count the same way as your requirement: everything logged except rejected entries.": "As horas contam do mesmo jeito que na sua exigência: tudo o que foi registrado, menos os registros recusados.",
  "New signer: the old signature was removed. Draw theirs below, or use the phone QR code.": "Novo assinante: a assinatura antiga foi removida. Desenhe a dele abaixo ou use o QR code no celular.",
  "What each entry needs": "O que cada registro precisa ter",
  "Who signs": "Quem assina",
  "Students sign on the Log Hours form before they can save.": "Os alunos assinam no formulário Registrar horas antes de salvar.",
  "Students must name a supervisor, who gets an emailed link and signs there to approve.": "Os alunos precisam informar um supervisor, que recebe um link por e-mail e assina lá para aprovar.",
  "Students sign on the form, and their supervisor signs on the emailed link to approve.": "Os alunos assinam no formulário, e o supervisor assina pelo link enviado por e-mail para aprovar.",
  "Link to your form": "Link para o seu formulário",
  "Google Form — students fill it in right on the Log Hours page, then tick a box to say they sent it.": "Formulário Google — os alunos preenchem direto na página Registrar horas e depois marcam uma caixa dizendo que enviaram.",
  "A Google Form opens right on the Log Hours page. Any other link (a PDF, a doc) is something students download, get signed, and upload. Leave blank if they get the form in class.": "Um Formulário Google abre direto na página Registrar horas. Qualquer outro link (um PDF, um documento) é algo que os alunos baixam, pedem para assinar e enviam. Deixe em branco se eles recebem o formulário na aula.",
  "This looks like the link for editing the form. Use Send → link in Google Forms instead, so students can fill it in.": "Isto parece o link de edição do formulário. Use Enviar → link no Google Forms, para os alunos poderem preencher.",
  "Short forms.gle links can’t open inside VolunTrack. Paste the full docs.google.com link to keep students on the page.": "Links curtos forms.gle não abrem dentro do VolunTrack. Cole o link completo do docs.google.com para manter os alunos na página.",
  "Note to students (optional)": "Mensagem para os alunos (opcional)",
  "Your supervisor must sign in blue or black ink.": "Seu supervisor precisa assinar com caneta azul ou preta.",
  "Question": "Pergunta",
  "Advisor name": "Nome do orientador",
  "Answer type": "Tipo de resposta",
  "Choices": "Opções",
  "First period, Second period, Third period": "Primeiro horário, Segundo horário, Terceiro horário",
  "Comma-separated. A question with no choices is dropped when you save.": "Separadas por vírgula. Uma pergunta sem opções é descartada ao salvar.",
  "Helper text (optional)": "Texto de ajuda (opcional)",
  "Required": "Obrigatório",
  "Add a question": "Adicionar uma pergunta",
  "{n} schools — {k} of them override at least one section.": "{n} escolas — {k} delas substituem pelo menos uma seção.",
