  "The new principal gets an email to accept and becomes the main admin of {school}. The current one stays as a co-admin and is signed out.": "O novo diretor recebe um e-mail para aceitar e se torna o admin principal de {school}. O atual continua como coadministrador e tem a sessão encerrada.",
  "Loading invites…": "Carregando convites…",
  "No invites sent": "Nenhum convite enviado",
