  "Set up": "Configurada",
  "Expired": "Expirado",
  "Someone new running the organization?": "Alguém novo vai cuidar da organização?",
  "Hand this organization’s account to them. They get an email to accept and set their own password. When they do, this login is removed from the organization and signed out.": "Passe a conta desta organização para essa pessoa. Ela recebe um e-mail para aceitar e criar a própria senha. Quando ela aceitar, este login é removido da organização e tem a sessão encerrada.",
  "They'll get an email with a link to set their own password and school code. The link expires in 3 days.": "Ela vai receber um e-mail com um link para criar a própria senha e o código da escola. O link expira em 3 dias.",
