  "Loading branding…": "Carregando identidade visual…",
  "Accent colour": "Cor de destaque",
  "A hex value. Used for accents on your sign-in page — not for text or button backgrounds, so any colour stays readable. Leave blank for the VolunTrack green.": "Um valor hexadecimal. Usado nos detalhes da sua página de login — não no texto nem no fundo dos botões, então qualquer cor continua legível. Deixe em branco para o verde do VolunTrack.",
  "Enter a hex value like #2f855a.": "Digite um valor hexadecimal como #2f855a.",
  "Preview": "Prévia",
  "Save branding": "Salvar identidade visual",
  "This branding applies to your organization’s own hostnames. Each school brands its own separately.": "Esta identidade visual vale para os endereços próprios da sua organização. Cada escola define a sua separadamente.",
  "Only your school’s sign-in page changes. The VolunTrack name and logo stay on the canonical site.": "Só a página de login da sua escola muda. O nome e o logo do VolunTrack continuam no site principal.",
  "Branding only appears on your own hostname. You don’t have a live domain yet — set one up under Custom domain first, then anything you save here shows on its sign-in page.": "A identidade visual só aparece no seu próprio endereço. Você ainda não tem um domínio ativo — configure um em Domínio próprio primeiro, e o que você salvar aqui aparece na página de login dele.",
  "Shown at sign-in on": "Aparece no login em",
