  "Entries no supervisor or event organizer has confirmed. They count for now; approve them, or send one back with a reason and it stops counting until the student fixes it.": "Registros que nenhum supervisor ou organizador de evento confirmou. Eles contam por enquanto; aprove-os, ou devolva um com o motivo e ele deixa de contar até o aluno corrigir.",
