  "What should the student fix? They see this.": "O que o aluno deve corrigir? Ele vai ver isto.",
  "Send back": "Devolver",
  "Showing the first 200. Approve or send back some to see more.": "Mostrando os primeiros 200. Aprove ou devolva alguns para ver mais.",
