  "This range hit the {n}-row limit, so the export is incomplete. Narrow the dates and run it again.": "Este período chegou ao limite de {n} linhas, então a exportação está incompleta. Reduza as datas e gere de novo.",
  "Showing 25 of {n}. The exports contain every student.": "Mostrando 25 de {n}. As exportações têm todos os alunos.",
  "Loading domains…": "Carregando domínios…",
  "Custom domains can be claimed and their ownership verified, but this server cannot issue certificates yet, so a domain cannot go live. Contact VolunTrack support.": "É possível registrar domínios próprios e verificar a propriedade, mas este servidor ainda não emite certificados, então o domínio não pode entrar no ar. Fale com o suporte do VolunTrack.",
  "Ownership verified": "Propriedade verificada",
  "Ownership not verified yet": "Propriedade ainda não verificada",
  "Add these two records at your DNS provider. The TXT record proves you own the domain; the CNAME sends visitors to VolunTrack.": "Adicione estes dois registros no seu provedor de DNS. O registro TXT prova que o domínio é seu; o CNAME manda os visitantes para o VolunTrack.",
