  "A hostname you already own, e.g. {example}. You will need access to its DNS settings.": "Um endereço que você já tem, ex.: {example}. Você vai precisar de acesso às configurações de DNS dele.",
  "New school year": "Novo ano letivo",
  "Undo": "Desfazer",
  "No students have a grade from Kindergarten to 12th to move up": "Nenhum aluno tem série do Jardim de infância ao 12º para avançar",
  "Print the graduation report for your seniors first: after this they are listed as Graduated, not 12th grade.": "Imprima primeiro o relatório de formatura dos seus formandos: depois disso eles aparecem como Formados, não como 12º ano.",
