  "Move up again anyway": "Avançar de novo mesmo assim",
  "Moving…": "Avançando…",
  "Move everyone up a grade": "Avançar todos uma série",
  "Move every student up a grade at the start of the year. 12th graders become Graduated. You can undo it for {n} days.": "Avance todos os alunos uma série no início do ano. Os do 12º ano viram Formados. Você pode desfazer por {n} dias.",
  "Last moved up on {date} (1 student).": "Último avanço em {date} (1 aluno).",
  "Last moved up on {date} ({n} students).": "Último avanço em {date} ({n} alunos).",
  "1 student stays as they are (College, Graduated, another label, or no grade).": "1 aluno continua como está (Faculdade, Formado, outra etiqueta ou sem série).",
  "{n} students stay as they are (College, Graduated, another label, or no grade).": "{n} alunos continuam como estão (Faculdade, Formado, outra etiqueta ou sem série).",
  "Grades were already moved up on {date}. Doing it again moves every student up another grade.": "As séries já foram avançadas em {date}. Fazer de novo avança cada aluno mais uma série.",
  "That partner is already on the list.": "Esse parceiro já está na lista.",
  "Partner organizations": "Organizações parceiras",
  "The nonprofits your schools work with, kept in one list. Students at your schools see it on Opportunities, and advisers also see the contact person.": "As ONGs com quem suas escolas trabalham, numa única lista. Os alunos das suas escolas a veem em Oportunidades, e os orientadores também veem a pessoa de contato.",
  "Add partner": "Adicionar parceiro",
  "Import CSV": "Importar CSV",
  "Count these as approved places at all my schools.": "Contar estes como lugares aprovados em todas as minhas escolas.",
  "They are added to each school's own list. Hours from other places are still counted, but advisers see them flagged to check.": "Eles são adicionados à lista de cada escola. Horas de outros lugares ainda contam, mas os orientadores as veem marcadas para conferir.",
  "No partners yet. Add one, or import a CSV.": "Nenhum parceiro ainda. Adicione um ou importe um CSV.",
  "A partner whose contact email matches the account they post events from gets a “District partner” label on those events for your students.": "Um parceiro cujo e-mail de contato é o mesmo da conta de onde publica eventos ganha a etiqueta “Parceiro do distrito” nesses eventos para seus alunos.",
  "CSV columns: {columns} (separate causes with semicolons).": "Colunas do CSV: {columns} (separe as causas com ponto e vírgula).",
  "Invite a whole class": "Convide uma turma inteira",
  "Paste your students' emails, or pick a CSV file from your roster. Students with an account accept in their Settings; everyone else gets an email with your join link. Up to 200 at a time.": "Cole os e-mails dos alunos ou escolha um arquivo CSV da sua lista. Alunos com conta aceitam nas Configurações; os outros recebem um e-mail com seu link de entrada. Até 200 por vez.",
  "A CSV with a header row can include Name (or First and Last name) and Grade columns. Each student’s grade is then set for them when they join.": "Um CSV com linha de cabeçalho pode incluir as colunas Nome (ou Nome e Sobrenome) e Série. A série de cada aluno é definida quando ele entra.",
  "That’s {n}; send up to 200 at a time.": "São {n}; envie até 200 por vez.",
  "Pick a CSV file": "Escolha um arquivo CSV",
  "No header row found, so only the email addresses were read.": "Nenhuma linha de cabeçalho encontrada, então só os e-mails foram lidos.",
  "Announce to your schools": "Avisar suas escolas",
  "Shows as a banner on each of your schools’ dashboards, marked as from your organization, and is emailed once.": "Aparece como banner no painel de cada uma das suas escolas, marcado como vindo da sua organização, e é enviado por e-mail uma vez.",
  "Send to": "Enviar para",
