  "Set up in 5 minutes": "Configure em 5 minutos",
  "Get your students on VolunTrack in five minutes. Students who open your link or scan the code join {school} without typing the code.": "Coloque seus alunos no VolunTrack em cinco minutos. Alunos que abrirem seu link ou escanearem o código entram em {school} sem digitar o código.",
  "Rank your schools by the hours their students log, e.g. “Most hours in November”. Students and advisers see school names and totals, never individual students.": "Classifique suas escolas pelas horas que os alunos registram, ex.: “Mais horas em novembro”. Alunos e orientadores veem os nomes das escolas e os totais, nunca alunos individuais.",
