  "The organizer of an event {name} signed up for sees this on their check-in list, only around the day of the event. It isn’t shown anywhere else.": "O organizador de um evento em que {name} se inscreveu vê isto na lista de check-in, só perto do dia do evento. Não aparece em nenhum outro lugar.",
