  "They send by themselves when you’re back online.": "Eles são enviados sozinhos quando você voltar a ficar online.",
  "Send now": "Enviar agora",
  "Saved on this device. It sends by itself when you’re back online.": "Salvo neste aparelho. É enviado sozinho quando você voltar a ficar online.",
  "Waiting to send": "Esperando para enviar",
  "Could not make the packet.": "Não foi possível montar o pacote.",
  "End-of-year packet": "Pacote de fim de ano",
  "One ZIP with a folder for each school: summary, every entry, and each student’s hours report.": "Um ZIP com uma pasta para cada escola: resumo, todos os registros e o relatório de horas de cada aluno.",
  "One ZIP with the summary, every entry, the approval history, certificates for students who met the requirement, and each student’s hours report.": "Um ZIP com o resumo, todos os registros, o histórico de aprovações, certificados para os alunos que cumpriram a exigência e o relatório de horas de cada aluno.",
