  "Making the packet…": "Montando o pacote…",
  "Download packet": "Baixar pacote",
  "School year runs August 1 to July 31. The ZIP has students’ personal information, so keep it somewhere safe.": "O ano letivo vai de 1º de agosto a 31 de julho. O ZIP tem informações pessoais dos alunos, então guarde em um lugar seguro.",
  "A parent or guardian must come with you to this event. Who is coming? (their name)": "Um pai, mãe ou responsável precisa vir com você a este evento. Quem vem? (nome)",
