  "When are you usually free?": "Quando você costuma estar livre?",
  "Tick the times that work for you. \"When I'm free\" then shows only events that start then. Only you see this.": "Marque os horários que funcionam para você. \"Quando estou livre\" passa a mostrar só eventos que começam nesses horários. Só você vê isso.",
  "Morning is before noon, afternoon noon to 5 PM, evening after 5 PM.": "Manhã é antes do meio-dia, tarde do meio-dia às 17h, noite depois das 17h.",
