  "Welcome tours": "Tours de boas-vindas",
  "which welcome tours you have finished or skipped, so each one shows only once on any device. Deleted with your account.": "quais tours de boas-vindas você terminou ou pulou, para cada um aparecer só uma vez em qualquer aparelho. Excluído junto com sua conta.",
