  "Switching from x2VOL, MobileServe or a spreadsheet? Upload a CSV with student email, date, activity and hours (organization, category and notes are optional). Hours come in approved, for students already at your school.": "Vindo do x2VOL, MobileServe ou de uma planilha? Envie um CSV com e-mail do aluno, data, atividade e horas (organização, categoria e observações são opcionais). As horas entram aprovadas, para alunos que já estão na sua escola.",
