  "Show-up rate counts volunteers you approved who were marked present or checked in, out of those plus anyone marked absent. Excused volunteers and anyone not yet marked aren't counted. Hours are approved hours logged on the task.": "A taxa de comparecimento conta os voluntários que você aprovou e que foram marcados como presentes ou fizeram check-in, entre esses mais os marcados como ausentes. Voluntários justificados e quem ainda não foi marcado não contam. As horas são as horas aprovadas registradas na tarefa.",
