  "Share the join link or put the flyer up. Students who use it land on your roster.": "Compartilhe o link de entrada ou coloque o folheto no mural. Os alunos que usarem entram na sua lista.",
  "Approve hours as they come in, here on the Students tab.": "Aprove as horas conforme chegam, aqui na aba Alunos.",
