  "Found a bug, have a feature request, or just want to say hi? We'd love to hear from you.": "Achou um bug, tem um pedido de recurso ou só quer dar um oi? Adoraríamos ouvir você.",
  "Check that a VolunTrack transcript is genuine and has not been changed since it was issued. No account needed. The file is checked by our server and not stored.": "Confira se um histórico do VolunTrack é autêntico e não foi alterado desde que foi emitido. Não precisa de conta. O arquivo é verificado pelo nosso servidor e não fica guardado.",
