  "Remember it. When you leave, tap your name here and type this PIN to check out.": "Guarde bem. Quando sair, toque no seu nome aqui e digite este PIN para fazer check-out.",
  "I’ll remember it": "Vou lembrar",
  "Volunteer of the month": "Voluntário do mês",
  "Give one student a shout-out. They and their parents get a notification and a certificate. Only they and your school see it.": "Dê um destaque para um aluno. Ele e os responsáveis recebem uma notificação e um certificado. Só eles e sua escola veem.",
  "Choose a student": "Escolha um aluno",
