  "Your students get a notification and see it on their dashboard.": "Seus alunos recebem uma notificação e veem isso no painel.",
  "You're going": "Você vai",
  "On the waitlist": "Na lista de espera",
  "Weekly family goal": "Meta semanal da família",
  "Goal met! 🎉": "Meta cumprida! 🎉",
  "Set a goal": "Definir uma meta",
  "Hours each week": "Horas por semana",
  "hours each week": "horas por semana",
  "Agree on a small number of hours together. You both see how the week is going.": "Combinem juntos um número pequeno de horas. Vocês dois veem como a semana está indo.",
  "Set with {name}": "Definida com {name}",
  "Could not save the weekly goal.": "Não foi possível salvar a meta semanal.",
  "Could not undo volunteer of the month.": "Não foi possível desfazer o voluntário do mês.",
